#include "opt/dau/dauTree.c"
int main(int argc,char **argv){Dss_Man_t *p=Dss_ManAlloc(6,0);int x[3]={2,3,2},y[3]={0};int a=Dss_ManOperation(p,DAU_DSD_AND,x,2,0,0);int b=Dss_ManOperation(p,DAU_DSD_XOR,x,2,0,0);int c=Dss_ManOperation(p,DAU_DSD_MUX,x,3,0,0);int ids[3]={a,b,c};for(int i=0;i<3;i++){int perm[6]={0,2,4,6,8,10};word *truth=Dss_ManComputeTruth(p,ids[i],6,perm);printf("%d %016llx\n",ids[i],(unsigned long long)truth[0]);Dss_ManPrintOne(stdout,p,ids[i],0);}unsigned char perm[6];y[0]=3;y[1]=a;int d=Dss_ManOperation(p,DAU_DSD_AND,y,2,perm,0);printf("combined %d perm %d %d %d\n",d,perm[0],perm[1],perm[2]);return 0;}
